import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();

const prompt = 'Explain the difference between machine learning and deep learning.';

const countResult = await client.messages.countTokens({
  model: 'claude-haiku-4-5-20251001',
  messages: [{ role: 'user', content: prompt }]
});

console.log(`Input tokens: ${countResult.input_tokens}`);

// Estimate cost
const inputPrice = 1.00 / 1_000_000;  // $1.00 per million
const estimatedCost = countResult.input_tokens * inputPrice;
console.log(`Estimated input cost: $${estimatedCost.toFixed(6)}`);

你将编写一个脚本，对三个不同的提示词分别计数 token、发起真实的 API 调用，并根据响应中的 usage 字段计算实际成本。

创建 `exercises/token-demo.js`（或 `.py`），运行以下内容：

**Node.js 版本：**
```javascript
import Anthropic from '@anthropic-ai/sdk';
import 'dotenv/config';

const client = new Anthropic();

// Haiku pricing
const INPUT_PRICE  = 1.00 / 1_000_000;
const OUTPUT_PRICE = 5.00 / 1_000_000;

const prompts = [
  'What is 2 + 2?',
  'Explain the concept of recursion in programming.',
  'Write a detailed comparison of Python and JavaScript for a beginner who wants to learn their first programming language, covering syntax, use cases, learning resources, and career prospects.'
];

for (const prompt of prompts) {
  // Count tokens first
  const count = await client.messages.countTokens({
    model: 'claude-haiku-4-5-20251001',
    messages: [{ role: 'user', content: prompt }]
  });

  // Make the real call
  const response = await client.messages.create({
    model: 'claude-haiku-4-5-20251001',
    max_tokens: 500,
    messages: [{ role: 'user', content: prompt }]
  });

  const inputTokens  = response.usage.input_tokens;
  const outputTokens = response.usage.output_tokens;
  const cost = (inputTokens * INPUT_PRICE) + (outputTokens * OUTPUT_PRICE);

  console.log(`\nPrompt: "${prompt.slice(0, 60)}..."`);
  console.log(`  Pre-call estimate: ${count.input_tokens} input tokens`);
  console.log(`  Actual input: ${inputTokens} tokens, output: ${outputTokens} tokens`);
  console.log(`  Cost: $${cost.toFixed(6)}`);
}
```

运行它：`node token-demo.js`

**需要观察的地方：**
- 简短的问题所使用的 token 数量明显少于长篇文章的请求
- 输出 token 数量会随着回答的复杂程度变化
- 即使是最长、最详细的回答，用 Haiku 计算下来也不到一分钱
- 调用前的预估值与实际的 input_tokens 非常接近
